final class MutableTokenBatch(initial: Seq[Token] = Seq.empty) {
  private val buf: mutable.ListBuffer[Token] = mutable.ListBuffer.from(initial)
  private var processed: Boolean = false

  def tokens: List[Token] = buf.toList

  def add(token: ***REDACTED*** Unit = {
    if (processed) throw new IllegalStateException("Batch already processed")
    buf += token
  }

  def markProcessed(): Unit = {
    processed = true
  }
