  def tokenize(value: Any): Token = ***REDACTED*** match {
    case null => Token("NULL", TokenType.NULL)

    case t: Tokenizable =>
      Token(t.toToken, TokenType.STRUCTURED)

    case s: String      => stringTokenizer.tokenize(s)
    case b: Array[Byte] => stringTokenizer.tokenize(b)

    case _: Int | _: Long | _: Short | _: Byte | _: Float | _: Double | _: BigDecimal | _: java.math.BigDecimal | _: BigInt | _: Number =>
      numericTokenizer.tokenize(value)

    case dt: LocalDateTime => temporalTokenizer.tokenize(dt)
    case d: LocalDate      => temporalTokenizer.tokenize(d)

    case other =>
      Token(String.valueOf(other), TokenType.STRING, Map("fallback" -> true))
