final class TokenRegistry[T] {
  private val registry: mutable.Map[String, TokenContainer[T]] = mutable.Map.empty
  private val handlers: mutable.ListBuffer[T => Option[Token]] = mutable.ListBuffer.empty

  def register(key: String, container: TokenContainer[T]): Unit = {
    registry.update(key, container)
  }

  def addHandler(handler: T => Option[Token]): Unit = {
    handlers += handler
  }

  def process(key: String): List[Option[Token]] = {
    registry.get(key) match {
      case None => Nil
      case Some(container) =>
        container.getAll.toList.map { item =>
          handlers.iterator.map(h => h(item)).collectFirst { case some @ Some(_) => some }.getOrElse(None)
        }
    }
  }
}

class TokenFunctor[T](protected val underlying: Option[T]) {
  def map[B](func: T => B): TokenFunctor[B] = new TokenFunctor(underlying.map(func))

  def flatMap[B](func: T => TokenFunctor[B]): TokenFunctor[B] = underlying match {
    case Some(v) => func(v)
    case None    => new TokenFunctor[B](None)
  }

  def getOrElse(default: => T): T = underlying.getOrElse(default)
}

object TokenFunctor {
  def apply[T](value: T): TokenFunctor[T] = new TokenFunctor(Option(value))
}

final class TokenMonad[T](under: Option[T]) extends TokenFunctor[T](under) {
  def ap[B](funcWrapped: TokenMonad[T => B]): TokenMonad[B] = {
    val out = for {
      v <- underlying
      f <- funcWrapped.underlying
    } yield f(v)

    new TokenMonad[B](out)
  }
}

object TokenMonad {
  def pure[T](value: T): TokenMonad[T] = new TokenMonad(Option(value))
}

private object JsonUtil {
  private def escapeString(s: String): String = {
    val sb = new StringBuilder(s.length + 16)
    sb.append('"')
    s.foreach {
      case '"' => sb.append("\\\"")
      case '\\' => sb.append("\\\\")
      case '\b' => sb.append("\\b")
      case '\f' => sb.append("\\f")
      case '\n' => sb.append("\\n")
      case '\r' => sb.append("\\r")
      case '\t' => sb.append("\\t")
      case c if c.isControl =>
        sb.append(f"\\u${c.toInt}%04x")
      case c => sb.append(c)
    }
    sb.append('"')
    sb.result()
  }

  private def renderCompact(value: Any): String = value match {
    case null          => "null"
    case s: String     => escapeString(s)
    case b: Boolean    => b.toString
    case i: Int        => i.toString
    case l: Long       => l.toString
    case d: Double     =>
      if (d.isNaN || d.isInfinity) "null" else String.format(Locale.ROOT, "%.15g", java.lang.Double.valueOf(d))
    case f: Float      =>
      val d = f.toDouble
      if (d.isNaN || d.isInfinity) "null" else String.format(Locale.ROOT, "%.15g", java.lang.Double.valueOf(d))
    case bd: BigDecimal           => bd.bigDecimal.toPlainString
    case bd: java.math.BigDecimal => bd.toPlainString
    case bi: BigInt               => bi.toString
    case n: Number                => String.valueOf(n)

    case m: Map[?, ?] =>
      val entries = m.iterator.collect { case (k: String, v) => s"${escapeString(k)}:${renderCompact(v)}" }.mkString(",")
      s"{$entries}"

    case it: Iterable[?] =>
      it.iterator.map(renderCompact).mkString("[", ",", "]")

    case arr: Array[?] =>
      arr.iterator.map(renderCompact).mkString("[", ",", "]")

    case other =>
      escapeString(String.valueOf(other))
  }

  private def indent(level: Int): String = "  " * level

  private def renderPretty(value: Any, level: Int): String = value match {
    case m: Map[?, ?] =>
      val fields = m.iterator.collect { case (k: String, v) => (k, v) }.toList
      if (fields.isEmpty) "{}"
      else {
        val inner = fields
          .map { case (k, v) => s"${indent(level + 1)}${escapeString(k)}: ${renderPretty(v, level + 1)}" }
          .mkString(",\n")
        s"{\n$inner\n${indent(level)}}"
      }

    case it: Iterable[?] =>
      val items = it.iterator.toList
      if (items.isEmpty) "[]"
      else {
        val inner = items.map(v => s"${indent(level + 1)}${renderPretty(v, level + 1)}").mkString(",\n")
        s"[\n$inner\n${indent(level)}]"
      }

    case arr: Array[?] =>
      renderPretty(arr.toList, level)

    case other => renderCompact(other)
  }

  def render(value: Any, pretty: Boolean): String =
    if (pretty) renderPretty(value, 0) else renderCompact(value)
}

final class JsonTokenizer(val pretty: Boolean = false) {
  def tokenize(value: Any): Token = ***REDACTED***
    val jsonStr = JsonUtil.render(value, pretty)
    Token(jsonStr, TokenType.STRUCTURED, Map("json" -> true))
  }

  def tokenizePath(value: Any, path: String): Option[Token] = {
    val parts = if (path.isEmpty) Nil else path.split("\\.").toList

    val extracted = parts.foldLeft(Option(value): Option[Any]) {
      case (None, _) => None
      case (Some(current), part) =>
        current match {
          case m: Map[?, ?] =>
            m.asInstanceOf[Map[String, Any]].get(part)

          case it: Seq[?] if part.forall(_.isDigit) =>
            val idx = part.toInt
            val seq = it.asInstanceOf[Seq[Any]]
            if (idx >= 0 && idx < seq.length) Some(seq(idx)) else None

          case it: List[?] if part.forall(_.isDigit) =>
            val idx = part.toInt
            val seq = it.asInstanceOf[List[Any]]
            if (idx >= 0 && idx < seq.length) Some(seq(idx)) else None

          case arr: Array[?] if part.forall(_.isDigit) =>
            val idx = part.toInt
            if (idx >= 0 && idx < arr.length) Some(arr(idx)) else None

          case _ => None
        }
    }

    extracted.map(tokenize)
  }
}

final class WhitespaceTokenizer(
  val lowercase: Boolean = false,
  val minLength: Int = 0,
  val maxLength: Option[Int] = None,
  val stripPunctuation: Boolean = false
) {
  private val punctuation: Set[Char] = ".,!?;:'\"()[]{}".toSet

  private def strip(word: String): String = {
    def dropLeading(s: String): String = s.dropWhile(punctuation.contains)
    def dropTrailing(s: String): String = s.reverse.dropWhile(punctuation.contains).reverse
    dropTrailing(dropLeading(word))
  }

  private def processToken(word: String): Option[String] = {
    val stripped = if (stripPunctuation) strip(word) else word
    val normalized = if (lowercase) stripped.toLowerCase(Locale.ROOT) else stripped

    if (normalized.length < minLength) None
    else {
      val truncated = maxLength match {
        case Some(max) if normalized.length > max => normalized.take(max)
        case _                                   => normalized
      }
      Option(truncated).filter(_.nonEmpty)
    }
  }

  private def wordsWithPositions(text: String): Vector[(String, Int, Int)] = {
    val m = "\\S+".r.pattern.matcher(text)
    val out = Vector.newBuilder[(String, Int, Int)]
    while (m.find()) {
      val w = text.substring(m.start(), m.end())
      out += ((w, m.start(), m.end()))
    }
    out.result()
  }

  def tokenize(text: String): List[Token] = {
    wordsWithPositions(text).zipWithIndex.flatMap { case ((word, _, _), i) =>
      processToken(word).map { processed =>
        Token(processed, TokenType.STRING, Map("position" -> i, "original" -> word))
      }
    }.toList
  }

  def tokenizeToStrings(text: String): List[String] = tokenize(text).map(_.value)

  def tokenizeWithPositions(text: String): List[(String, Int, Int)] = {
    wordsWithPositions(text).flatMap { case (word, start, end) =>
      processToken(word).map(p => (p, start, end))
    }.toList
  }

  def countTokens(text: String): Int = tokenize(text).length
}

final class TokenizerBuilder[T] {
  private val normalizers: mutable.ListBuffer[String => String] = mutable.ListBuffer.empty
  private val validators: mutable.ListBuffer[T => Boolean] = mutable.ListBuffer.empty
  private var metadata: Map[String, Any] = Map.empty

  def withNormalizer(normalizer: String => String): TokenizerBuilder[T] = {
    normalizers += normalizer
    this
  }

  def withValidator(validator: T => Boolean): TokenizerBuilder[T] = {
    validators += validator
    this
  }

  def withMetadata(kvs: (String, Any)*): TokenizerBuilder[T] = {
    metadata = metadata ++ kvs
    this
  }

  def build(): T => Token = ***REDACTED***
    val builtNormalizers = normalizers.toList
    val builtValidators = validators.toList
    val builtMetadata = metadata

    (value: T) => {
      builtValidators.foreach { v =>
        if (!v(value)) throw new IllegalArgumentException(s"Validation failed for $value")
      }

      val normalized = builtNormalizers.foldLeft(String.valueOf(value)) { (s, f) => f(s) }
      Token(normalized, TokenType.STRING, builtMetadata)
    }
  }
}
