private object JsonUtil {
  private def escapeString(s: String): String = {
    val sb = new StringBuilder(s.length + 16)
    sb.append('"')
    s.foreach {
      case '"' => sb.append("\\\"")
      case '\\' => sb.append("\\\\")
      case '\b' => sb.append("\\b")
      case '\f' => sb.append("\\f")
      case '\n' => sb.append("\\n")
      case '\r' => sb.append("\\r")
      case '\t' => sb.append("\\t")
      case c if c.isControl =>
        sb.append(f"\\u${c.toInt}%04x")
      case c => sb.append(c)
    }
    sb.append('"')
    sb.result()
  }

  private def renderCompact(value: Any): String = value match {
    case null          => "null"
    case s: String     => escapeString(s)
    case b: Boolean    => b.toString
    case i: Int        => i.toString
    case l: Long       => l.toString
    case d: Double     =>
      if (d.isNaN || d.isInfinity) "null" else String.format(Locale.ROOT, "%.15g", java.lang.Double.valueOf(d))
    case f: Float      =>
      val d = f.toDouble
      if (d.isNaN || d.isInfinity) "null" else String.format(Locale.ROOT, "%.15g", java.lang.Double.valueOf(d))
    case bd: BigDecimal           => bd.bigDecimal.toPlainString
    case bd: java.math.BigDecimal => bd.toPlainString
    case bi: BigInt               => bi.toString
    case n: Number                => String.valueOf(n)

    case m: Map[?, ?] =>
      val entries = m.iterator.collect { case (k: String, v) => s"${escapeString(k)}:${renderCompact(v)}" }.mkString(",")
      s"{$entries}"

    case it: Iterable[?] =>
      it.iterator.map(renderCompact).mkString("[", ",", "]")

    case arr: Array[?] =>
      arr.iterator.map(renderCompact).mkString("[", ",", "]")

    case other =>
      escapeString(String.valueOf(other))
  }

  private def indent(level: Int): String = "  " * level

  private def renderPretty(value: Any, level: Int): String = value match {
    case m: Map[?, ?] =>
      val fields = m.iterator.collect { case (k: String, v) => (k, v) }.toList
      if (fields.isEmpty) "{}"
      else {
        val inner = fields
          .map { case (k, v) => s"${indent(level + 1)}${escapeString(k)}: ${renderPretty(v, level + 1)}" }
          .mkString(",\n")
        s"{\n$inner\n${indent(level)}}"
      }

    case it: Iterable[?] =>
      val items = it.iterator.toList
      if (items.isEmpty) "[]"
      else {
        val inner = items.map(v => s"${indent(level + 1)}${renderPretty(v, level + 1)}").mkString(",\n")
        s"[\n$inner\n${indent(level)}]"
      }

    case arr: Array[?] =>
      renderPretty(arr.toList, level)

    case other => renderCompact(other)
  }

  def render(value: Any, pretty: Boolean): String =
    if (pretty) renderPretty(value, 0) else renderCompact(value)
}

