final class WhitespaceTokenizer(
  val lowercase: Boolean = false,
  val minLength: Int = 0,
  val maxLength: Option[Int] = None,
  val stripPunctuation: Boolean = false
) {
  private val punctuation: Set[Char] = ".,!?;:'\"()[]{}".toSet

  private def strip(word: String): String = {
    def dropLeading(s: String): String = s.dropWhile(punctuation.contains)
    def dropTrailing(s: String): String = s.reverse.dropWhile(punctuation.contains).reverse
    dropTrailing(dropLeading(word))
  }

  private def processToken(word: String): Option[String] = {
    val stripped = if (stripPunctuation) strip(word) else word
    val normalized = if (lowercase) stripped.toLowerCase(Locale.ROOT) else stripped

    if (normalized.length < minLength) None
    else {
      val truncated = maxLength match {
        case Some(max) if normalized.length > max => normalized.take(max)
        case _                                   => normalized
      }
      Option(truncated).filter(_.nonEmpty)
    }
  }

  private def wordsWithPositions(text: String): Vector[(String, Int, Int)] = {
    val m = "\\S+".r.pattern.matcher(text)
    val out = Vector.newBuilder[(String, Int, Int)]
    while (m.find()) {
      val w = text.substring(m.start(), m.end())
      out += ((w, m.start(), m.end()))
    }
    out.result()
  }

  def tokenize(text: String): List[Token] = {
    wordsWithPositions(text).zipWithIndex.flatMap { case ((word, _, _), i) =>
      processToken(word).map { processed =>
        Token(processed, TokenType.STRING, Map("position" -> i, "original" -> word))
      }
    }.toList
  }

  def tokenizeToStrings(text: String): List[String] = tokenize(text).map(_.value)

  def tokenizeWithPositions(text: String): List[(String, Int, Int)] = {
    wordsWithPositions(text).flatMap { case (word, start, end) =>
      processToken(word).map(p => (p, start, end))
    }.toList
  }

  def countTokens(text: String): Int = tokenize(text).length
}

